bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_CONTAINER_NOT_RUNNING; exit 61; }
if docker logs --tail 140 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$';then echo STK04_ALREADY_READY=PASS; exit 0;fi
docker exec -i "$name" node --input-type=module <<'JS'
import {createCreatorPollingRuntime} from "./src/runtime/creatorPollingMain.mjs";
try {
  const rt=await createCreatorPollingRuntime();
  await rt.close();
  console.log("STK04_RUNTIME_CONSTRUCTION_PASS");
} catch (e) {
  const c=String(e?.code??"");
  const m=String(e?.message??"");
  if(c==="28P01")process.exitCode=80;
  else if(c==="3D000")process.exitCode=81;
  else if(c==="42501")process.exitCode=82;
  else if(c==="ECONNREFUSED")process.exitCode=83;
  else if(c==="ENOTFOUND"||c==="EAI_AGAIN")process.exitCode=84;
  else if(c==="ETIMEDOUT"||c==="UND_ERR_CONNECT_TIMEOUT")process.exitCode=85;
  else if(c==="ERR_MODULE_NOT_FOUND")process.exitCode=86;
  else if(c==="ENOENT"||c==="EACCES")process.exitCode=87;
  else if(/VideoBot source module missing owned dependencies|verified GATE owner provider missing/.test(m))process.exitCode=88;
  else if(/CREATOR_POLL_EXISTING_WEBHOOK_MUST_NOT_BE_REPLACED/.test(m))process.exitCode=89;
  else if(/CREATOR_POLL_SCHEMA_INCOMPLETE|VideoBot migration/.test(m))process.exitCode=90;
  else if(/verified bot|identity|CREATOR_BOT|TELEGRAM|HTTP/i.test(m))process.exitCode=91;
  else if(/relation .* does not exist|syntax error|already exists|duplicate|constraint/i.test(m))process.exitCode=92;
  else if(/getMe|401|403|404|429/.test(m))process.exitCode=93;
  else if(/CREATOR_POLL_/.test(m))process.exitCode=94;
  else process.exitCode=95;
}
JS
